import { expectStatus, test, expect } from "../../fixtures";

test("Audit trails from another tenant are invisible", { tag: "@AUD-02" }, async ({ apiAs, factory }) => {
  // Arrange
  const otherTenant = await apiAs("otherTenant");
  const member = await apiAs("member");
  const vendor = await factory.vendor({ as: "otherTenant" });
  // Confirm the vendor exists in the other tenant, so the 404 below reflects tenancy, not a missing vendor.
  expect(
    (await expectStatus<{ id: string }>(await otherTenant.get(`/api/vendors/${vendor.id}`), 200)).id,
  ).toBe(vendor.id);

  // Act
  const response = await member.get(`/api/vendors/${vendor.id}/audit`);

  // Assert
  await expectStatus(response, 404);
});
